package method_argument2;

public class square_with_parameter_without_return {
	
	public void square(int a)
	{
		int s=a*a;
		
		System.out.println(s);
		
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		square_with_parameter_without_return s=new square_with_parameter_without_return();
		
	s.square(4);
		
	}

}
